package ama.api;
import ama.storage.Task11B3LocalDecision;import ama.storage.Task11B3LocalDecision.Binding;import ama.contract.IdentityContracts.*;import ama.transcript.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Real controller lookup-first and fresh recover branches; mocked DB/service boundaries, no actual SQL. */
class Task11B3LocalDecisionWireTest {
 static final String M="36db643e-5fbd-4f9a-9a85-a7e6b7d76e38",P="142a236c-bcd6-4608-8e93-2dd5446c5fa9",T="3588aaba-ecfa-4889-8954-46c1454447d4",E="65fa6b21-22da-4a2e-a886-341b16978106",F="1431080e-9b05-4913-9355-db3fa5b0c39a",A="owner",TIME="2026-10-26 05:20:00.123000";
 static final ObjectMapper JSON=new ObjectMapper();static final Binding B=new Binding(T,P,F,"controlled-kb","library","root",A,E,"3");
 static ObjectNode fresh(){var d=JSON.createObjectNode();d.put("task_id",T).put("publication_id",P).put("submission_no",3).put("confirmation_id",F).put("provider_id",B.provider()).put("library_id",B.library()).put("folder_id",B.folder()).put("local_state","NEVER_MARKED").put("local_reason","EXPIRED_UNMARKED_ABANDONED").put("local_decided_by",A).put("local_attempt_no",0).put("local_execution_id",E).put("local_decided_at",TIME);return JSON.createObjectNode().put("taskId",T).put("httpStatus",200).put("replayed",false).set("decision",d);}
 static ObjectNode replay(){var d=JSON.createObjectNode();d.put("localState","NEVER_MARKED").put("reason","EXPIRED_UNMARKED_ABANDONED").put("decidedBy",A).put("attemptNoToken","0").put("executionId",E).put("decidedAt","2026-10-26T05:20:00.123");return JSON.createObjectNode().put("taskId",T).put("publicationId",P).put("submissionNoToken","3").put("confirmationId",F).put("providerId",B.provider()).put("libraryId",B.library()).put("folderId",B.folder()).put("httpStatus",200).put("replayed",true).set("decision",d);}
 @Test void actualControllerMissRecoverThenQueryHitUseDistinctRealWireShapes()throws Exception {
  var queries=mock(JdbcPublicationQueries.class);var service=mock(JdbcPublicationLocalRecovery.class);var runtime=new MinutesConfiguration.Runtime(null,null,null,null,null,null,null,service,65536);var actor=new Actor(A,Status.ACTIVE,Set.of(Role.USER));var session=new ResolvedSession(actor,"T".repeat(43),Instant.now().plusSeconds(60));
  when(queries.lookup(any(),anyString(),anyString(),anyString(),any(String[].class))).thenReturn(Optional.empty()).thenReturn(Optional.of(JSON.convertValue(replay(),Map.class)));when(service.recover(eq(actor),eq(M),eq(P),eq(T),eq("local-key"),eq(13L),eq(6L),anyString())).thenReturn(JSON.convertValue(fresh(),Map.class));
  var mvc=MockMvcBuilders.standaloneSetup(new PublicationController(runtime,null,null,queries)).setControllerAdvice(new PublicationErrors()).build();var wire=new ArrayList<JsonNode>();
  for(int i=0;i<2;i++){var response=mvc.perform(post("/api/v1/meetings/"+M+"/publications/"+P+"/local-recoveries").requestAttr(SessionSecurityFilter.SESSION,session).header("Idempotency-Key","local-key").contentType("application/json").content("{\"expectedRevisionToken\":\"13\",\"expectedPublicationRevisionToken\":\"6\",\"taskId\":\""+T+"\"}")).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());wire.add(JSON.readTree(response.getContentAsByteArray()));}
  assertTrue(wire.getFirst().path("decision").has("local_state"));assertTrue(wire.getLast().path("decision").has("localState"));assertNotEquals(wire.getFirst().path("decision"),wire.getLast().path("decision"));assertEquals(Task11B3LocalDecision.normalize(wire.getFirst(),B),Task11B3LocalDecision.normalize(wire.getLast(),B));assertEquals(6,Task11B3LocalDecision.normalize(wire.getFirst(),B).size());verify(service,times(1)).recover(eq(actor),eq(M),eq(P),eq(T),eq("local-key"),eq(13L),eq(6L),anyString());verifyNoMoreInteractions(service);
 }
 @Test void sameBusinessDecisionNormalizesMicrosTokensAndNewKeySnakeAck(){assertEquals(Task11B3LocalDecision.normalize(fresh(),B),Task11B3LocalDecision.normalize(replay(),B));assertEquals(Task11B3LocalDecision.normalize(replay(),B),Task11B3LocalDecision.fromSealedRow(fresh().get("decision"),B));var changed=fresh();((ObjectNode)changed.get("decision")).put("local_decided_at","2026-10-26 05:20:00.123001");assertNotEquals(Task11B3LocalDecision.normalize(replay(),B),Task11B3LocalDecision.fromSealedRow(changed.get("decision"),B));var again=fresh();again.put("replayed",true);assertEquals(Task11B3LocalDecision.normalize(fresh(),B),Task11B3LocalDecision.normalize(again,B));}
 @Test void exactMinuteLocalDateTimeToStringMatchesSqlSecondsAndSealedRow(){String minute=java.time.LocalDateTime.of(2026,10,26,5,20).toString();assertEquals("2026-10-26T05:20",minute);var sql=fresh();((ObjectNode)sql.get("decision")).put("local_decided_at","2026-10-26 05:20:00.000000");var iso=replay();((ObjectNode)iso.get("decision")).put("decidedAt",minute);var actual=Task11B3LocalDecision.normalize(sql,B);assertEquals(actual,Task11B3LocalDecision.normalize(iso,B));var row=sql.get("decision").deepCopy();((ObjectNode)row).put("local_decided_at",minute);assertEquals(actual,Task11B3LocalDecision.fromSealedRow(row,B));}
 @Test void rejectsChangedMissingMixedAndUnknownFields(){
  var mutations=new ArrayList<ObjectNode>();for(String field:List.of("taskId","publicationId","confirmationId","providerId","libraryId","folderId","submissionNoToken")){var r=replay();r.put(field,"wrong");mutations.add(r);}for(String field:List.of("localState","reason","decidedBy","executionId","attemptNoToken","decidedAt")){var r=replay();((ObjectNode)r.get("decision")).put(field,"wrong");mutations.add(r);r=replay();((ObjectNode)r.get("decision")).remove(field);mutations.add(r);}var mixed=fresh();((ObjectNode)mixed.get("decision")).put("localState","NEVER_MARKED");mutations.add(mixed);var unknown=replay();((ObjectNode)unknown.get("decision")).put("extra",true);mutations.add(unknown);for(String field:List.of("task_id","publication_id","confirmation_id","provider_id","library_id","folder_id","submission_no","local_state","local_reason","local_decided_by","local_attempt_no","local_execution_id","local_decided_at")){var r=fresh();((ObjectNode)r.get("decision")).remove(field);mutations.add(r);r=fresh();((ObjectNode)r.get("decision")).put(field,"wrong");mutations.add(r);}for(var r:mutations)assertThrows(AssertionError.class,()->Task11B3LocalDecision.normalize(r,B));
 }
 @Test void rejectsLossyOrNoncanonicalAttemptAndTime(){for(JsonNode value:List.of(JSON.getNodeFactory().numberNode(0),TextNode.valueOf("00"),TextNode.valueOf("+0"),TextNode.valueOf("٠"),NullNode.instance)){var r=replay();((ObjectNode)r.get("decision")).set("attemptNoToken",value);assertThrows(AssertionError.class,()->Task11B3LocalDecision.normalize(r,B));}for(String time:List.of("2026-10-26T05:20:00Z","2026-02-30 05:20:00.123","2026-10-26 05:20:00.1234567","2026-10-26 05:20","bad")){var r=replay();((ObjectNode)r.get("decision")).put("decidedAt",time);assertThrows(AssertionError.class,()->Task11B3LocalDecision.normalize(r,B));}}
}